#include <bits/stdc++.h>
using namespace std;

long long gs(vector<long long>&p,int n, int x, int y){
    int pos = x+2*y;
    int tt = 3*n-2*x-y;
    
    return 6ll*p[x]+(p[pos]-p[x])*4ll+3ll*(p[tt]-p[pos]);
}



int main() {
	int t;
	cin>>t;
	while(t--){
	    int n;
	    cin>>n;
	    vector<long long>a(3*n);
	    
	    for(int i=0;i<3*n;i++)
	        cin>>a[i];
	        
	    sort(a.begin(),a.end(),greater<long long>());
	    
	    vector<long long>p(3*n+1,0);
	    
	    for(int i=0;i<3*n;i++){
	        p[i+1] = p[i]+a[i];
	    }
	    
	    long long ans = 0;
	    
	    for(int i = 0;i<=n;i++){
	        int l=0,r=n-i;
	        while(r-l>3){
	            int x=(l+(r-l)/3);
	            int y = r-(r-l)/3;
	            
	            long long v1 = gs(p,n,i,x);
	            long long v2 = gs(p,n,i,y);
	            
	            if(v1<v2){
	                l = x+1;
	            }else{
	                r = y-1;
	            }
	        }
	        
	        for(int k=l;k<=r;k++){
	            ans = max(ans,gs(p,n,i,k));
	        }
	        
	    }
	    
	    cout<<ans<<endl;
	}

}
